// Linked institutional team drafts are historical/read-only until controlled execution is connected.
function teamActivityProtectedSnapshot(){const ids=new Set(db.projects.filter(p=>p.teamIntakeProvenance).map(p=>p.id));return JSON.stringify({projects:db.projects.filter(p=>ids.has(p.id)),intakes:(db.activityIntakes||[]).filter(r=>r.teamHandoff||ids.has(r.projectId))})}
function teamActivityCommandReference(args,context){const ids=new Set(db.projects.filter(p=>p.teamIntakeProvenance).map(p=>p.id));for(const r of db.activityIntakes||[])if(r.teamHandoff||ids.has(r.projectId))ids.add(r.id);const inspect=v=>typeof v==='string'?ids.has(v):v&&typeof v==='object'?Object.values(v).some(inspect):false;return inspect(args)||inspect(context)}
const teamActivityPriorCanEdit=proposalCanEdit;proposalCanEdit=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorCanEdit(p)};
const teamActivityPriorCanSubmit=proposalCanSubmit;proposalCanSubmit=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorCanSubmit(p)};
const teamActivityPriorApprover=proposalApprover;proposalApprover=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorApprover(p)};
const teamActivityPriorAdvance=advance;advance=function(next){if(current()?.teamIntakeProvenance)return toast('This institutional team draft requires its controlled activity workflow. Permission to start is separate.');return teamActivityPriorAdvance(next)};
const teamActivityPriorOverview=projectOverview;projectOverview=function(p){if(!p?.teamIntakeProvenance)return teamActivityPriorOverview(p);return `<h2>Linked team activity</h2><p>${esc(p.title)} · ${esc(label(p.state))}</p><p>${esc(p.description)}</p><p>Programme: ${esc(p.programme)} · Type: ${esc(p.type)} · Due: ${esc(p.due)}</p><h3>Confirmed team</h3>${tableHTML(['Student account','Responsibility'],p.members.map(id=>[esc(name(id)),id===p.owner?'Team lead':'Member']))}<p>Assigned mentor: ${esc(name(p.mentor))}</p><p>The final-approved intake and its history are preserved. ${p.state==='STARTED'?'Start is recorded. Further task tracking requires the controlled activity workflow.':'This draft is read-only. Editing, submission, approval and permission to start require the controlled activity workflow.'}</p>`};
